package glitch

import data.glitch_lib

# Sensitive field names that indicate password/credential storage
sensitive_fields := {
    "password", "passwd", "pwd", "secret", "credentials",
    "auth_token", "api_key", "access_key", "private_key",
    "master_password", "admin_password", "root_password",
    "database_password", "db_password"
}

# Helper to check if a field name is sensitive
is_sensitive_field(name) {
    lower_name := lower(name)
    sensitive_fields[_] == lower_name
}

# Helper to check if a string value looks like a hardcoded password (not a variable reference or function call)
is_hardcoded_value(value) {
    value.ir_type == "String"
    not looks_like_variable_reference(value.value)
    not looks_like_secret_reference(value.value)
}

looks_like_variable_reference(str) {
    regex.match("^\\$\\{.*\\}$", str)
}

looks_like_variable_reference(str) {
    regex.match("^var\\.", str)
}

looks_like_variable_reference(str) {
    regex.match("^data\\.", str)
}

looks_like_variable_reference(str) {
    regex.match("^module\\.", str)
}

looks_like_variable_reference(str) {
    regex.match("^local\\.", str)
}

looks_like_secret_reference(str) {
    regex.match("(?i)vault|secret|parameter|key.?vault|secrets.?manager|kms|hashicorp", str)
}

looks_like_secret_reference(str) {
    regex.match("(?i)get_secret|read_secret|data_source|lookup", str)
}

# Check for default/example/test passwords in descriptions or values
is_suspicious_password_value(str) {
    regex.match("(?i)^(password|pass|123|admin|root|test|demo|example|default|changeme|change.?me|secret)$", str)
}

is_suspicious_password_value(str) {
    regex.match("(?i)^(.)\1+$", str)  # repeated character
}

# Traverse nested structures to find hardcoded sensitive values in KeyValue pairs
find_hardcoded_in_expr(expr, found) {
    expr.ir_type == "Hash"
    [_, val] := walk(expr.value)
    val.ir_type == "KeyValue"
    is_sensitive_field(val.name)
    is_hardcoded_value(val.value)
    found := val
}

find_hardcoded_in_expr(expr, found) {
    expr.ir_type == "Array"
    [_, elem] := walk(expr.value)
    find_hardcoded_in_expr(elem, found)
}

find_hardcoded_in_expr(expr, found) {
    expr.ir_type == "KeyValue"
    is_sensitive_field(expr.name)
    is_hardcoded_value(expr.value)
    found := expr
}

# Check for sensitive attributes in atomic units
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_sensitive_field(attr.name)
    is_hardcoded_value(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Sensitive credentials should not be hardcoded; use secret management systems instead. (CWE-259)"
    }
}

# Check for sensitive variables (at unit block level)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    is_sensitive_field(var.name)
    is_hardcoded_value(var.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Sensitive credentials should not be hardcoded; use secret management systems instead. (CWE-259)"
    }
}

# Check for hardcoded passwords in nested structures (hashes, arrays within attributes)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.value.ir_type in {"Hash", "Array"}
    find_hardcoded_in_expr(attr.value, found)

    result := {
        "type": "sec_hard_pass",
        "element": found,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Sensitive credentials should not be hardcoded; use secret management systems instead. (CWE-259)"
    }
}

# Check for suspicious password values that look like defaults or test values
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_sensitive_field(attr.name)
    attr.value.ir_type == "String"
    is_suspicious_password_value(attr.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Detected suspicious hardcoded password value. Use secret management systems instead. (CWE-259)"
    }
}

